(p/'SHA256SUMS.json').write_text(json.dumps({f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in p.iterdir() if f.is_file() and f.name!='SHA256SUMS.json'},indent=2));print('PASS',j['checks'],'checks;',j['thermal_unique_pairs'],'unique pairs;',mx)
